export type analyzePrimerResponse = analyzePrimerResponseSuccess | analyzePrimerResponseError;

export const getAnalyzePrimerUrl = (params: AnalyzePrimerParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/tools/primers/analyze?${stringifiedParams}`
    : `/api/tools/primers/analyze`;
};

export const analyzePrimer = async (
  params: AnalyzePrimerParams,
  options?: RequestInit
): Promise<analyzePrimerResponse> => {
  return customFetch<analyzePrimerResponse>(getAnalyzePrimerUrl(params), {
    ...options,
    method: 'POST',
  });
};

