export const getGetResourceByExternalIdExternalResourceByExternalIdGetUrl = (
  params: GetResourceByExternalIdExternalResourceByExternalIdGetParams
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/external/resource/by-external-id?${stringifiedParams}`
    : `/external/resource/by-external-id`;
};

